import types

# quick trace by re-running internal steps
def trace():
    from syntax import PolicyError
    def cols(path):
        return tuple(name_to_col[x] for x in path)
    match_ids, match_paths = {}, []
    nm_ids, nm_atoms = {}, []
    complex_rules = []
    def mpid(pc):
        i = match_ids.get(pc)
        if i is None:
            i = len(match_paths); match_ids[pc] = i; match_paths.append(pc)
        return i
    def nnid(kind, pc):
        key = (kind, pc)
        i = nm_ids.get(key)
        if i is None:
            i = len(nm_atoms); nm_ids[key] = i; nm_atoms.append((kind, pc))
        return i
    def conv(node):
        kind = node[0]
        if kind == 'match': return ('M', mpid(cols(node[1])))
        if kind in ('startswith','endswith','contains'): return ('N', nnid(kind, cols(node[1])))
        if kind == 'not': return ('n', conv(node[1]))
        return (kind, conv(node[1]), conv(node[2]))
    for pred, action in rules:
        print("pred:", pred, "action:", action, "is simple:", pred[0]=='match')
        if pred[0] == 'match':
            pass
        else:
            complex_rules.append((action, conv(pred)))
    print("complex_rules:", complex_rules)
    ncols = 3
    nm_trans, nm_accept = [], []
    for kind, path in nm_atoms:
        t, acc = cc._atom_automaton(kind, path, ncols)
        nm_trans.append(t); nm_accept.append(acc)
    print("nm_trans:", nm_trans, "nm_accept:", nm_accept)
    nnm = len(nm_atoms)
    nm_start = tuple(0 for _ in range(nnm))
    state_node = [0]; state_nm = [nm_start]; lookup = {(0, nm_start): 0}
    state_trans = []
    i = 0
    children = [{}]
    while i < len(state_node):
        node = state_node[i]; nm = state_nm[i]
        row = [0]*ncols
        for c in range(ncols):
            nnode = children[node].get(c, -1) if node >= 0 else -1
            ntuple = tuple(nm_trans[k][nm[k]][c] for k in range(nnm))
            key = (nnode, ntuple)
            j = lookup.get(key)
            if j is None:
                j = len(state_node); lookup[key] = j
                state_node.append(nnode); state_nm.append(ntuple)
            row[c] = j
        state_trans.append(row)
        i += 1
    print("states:", state_node, state_nm, state_trans)
    ns = len(state_node)
    used_match, used_nm = set(), set()
    def gather(node):
        kind = node[0]
        if kind == 'M': used_match.add(node[1])
        elif kind == 'N': used_nm.add(node[1])
        elif kind == 'n': gather(node[1])
        else: gather(node[1]); gather(node[2])
    for _a, t in complex_rules: gather(t)
    print("used:", used_match, used_nm)
    masks = {}
    for nid in used_nm:
        masks[('N', nid)] = bytearray(ns)
    for i in range(ns):
        nm = state_nm[i]
        for nid in used_nm:
            if nm[nid] in nm_accept[nid]:
                masks[('N', nid)][i] = 1
    print("masks:", masks)
    mask_int = {k: int.from_bytes(v, 'little') for k, v in masks.items()}
    print("mask_int:", mask_int)
trace()
